<section class="panel"><div class="table-wrap"><table><thead><tr><th>No</th><th>Judul Buku</th><th>Mata Pelajaran</th><th>Kelas</th><th>Semester</th><th>Stok Tersedia</th><th>Aksi</th></tr></thead><tbody><?php if ($data_buku): foreach ($data_buku as $i => $row): ?><tr><td><?= $i+1 ?></td><td><strong><?= h($row->nama_buku) ?></strong></td><td><?= h($row->mata_pelajaran ?? 'Umum') ?></td><td><?= h($row->kelas ?? 'Umum') ?></td><td><?= h($row->semester ?? 'Umum') ?></td><td><span class="pill <?= (int)$row->stok > 0 ? 'pill-green' : 'pill-amber' ?>"><?= (int)$row->stok > 0 ? (int)$row->stok . ' buku' : 'Habis' ?></span></td><td><div class="row-actions"><a class="btn btn-small btn-light" href="<?= h(app_url('controllers/c_buku.php?aksi=edit&kode_buku=' . (int)$row->kode_buku)) ?>">Edit</a><form method="post" action="<?= h(app_url('controllers/c_buku.php?aksi=hapus')) ?>" onsubmit="return confirm('Hapus buku ini?')"><input type="hidden" name="kode_buku" value="<?= (int)$row->kode_buku ?>"><button type="submit" class="btn btn-small btn-danger">Hapus</button><?= csrf_field() ?></form></div></td></tr><?php endforeach; else: ?><tr><td colspan="7" class="empty">Belum ada data buku mata pelajaran.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
